            setPecho(""); setPierna(""); setCadera(""); setComentarios("");
            setFotos({ frente: null, espalda: null, perfDer: null, perfIzq: null });
            setFotosPreview({ frente: null, espalda: null, perfDer: null, perfIzq: null });
